/**
 * Scoped per testing.md: this component's own contract (given props, does it render the right
 * branch and wire the right handler) — not ZimmProductName/ZimmProductPrice/ZimmSizeChipGroup's
 * own internal logic, which is already proven in their own index.test.tsx files. All three are
 * lightweight, side-effect-free presentational components, so composing them directly for real
 * (rather than mocking them out) still costs nothing and gives genuine integration confidence
 * that this component passes them the right props — same precedent as
 * zimmProductCardMedia/index.test.tsx composing the real ZimmSlideIndicator.
 *
 * Only `useMultiStyleConfig` is mocked (this component's own 11 parts). `useStyleConfig` (used
 * internally by ZimmProductName) is left real/unmocked — it resolves an unregistered recipe key
 * to `{}` gracefully with no ChakraProvider present, exactly as ZimmProductName's own
 * (unmocked) index.test.tsx already relies on; only the multi-part hook needs a mock here (see
 * zimmSizeChipGroup/index.test.tsx's identical comment on this same distinction).
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, within, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { ZimmProductCardContent } from './index';
import type { ZimmProductCardContentProps } from './index';
import { ZimmProductCardContent as ZimmProductCardContentRecipe } from './zimmProductCardContent.css';
import type { ZimmSizeChipValue } from '../zimmSizeChipGroup';
import { CARD_SLOT } from '../../zimmProductCardShared';
// Real registered foundation token, not a hardcoded '48em' — so this test can't silently drift
// from the recipe's own media query key if the foundation value ever changes.
import { breakpoints } from 'app/theme/foundation';

// Flat parts object covering only this component's own recipe. ZimmProductPrice/
// ZimmSizeChipGroup/ZimmSizeChip's own `styles.X` reads resolve to `undefined` under this same
// mock, which is a legal, harmless `__css` value — same precedent
// zimmSizeChipGroup/index.test.tsx documents for ZimmSizeChip's own unresolved `styles.chip`.
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({
      root: {},
      nameRow: {},
      nameLink: {},
      bagWrapper: {},
      bagButton: {},
      attributesRow: {},
      colourText: {},
      sizeText: {},
      priceWrapper: {},
      sizeChipWrapper: {},
      notifyMeButton: {},
    }),
  };
});

// ZimmIcon: known Vitest SVG side-effect issue (.claude/rules/testing.md). The bag button's
// accessible name comes from the button's own aria-label, not the icon, so the icon can safely
// resolve to null rather than needing to forward any props. Mocked at the same relative
// specifier this component imports it from.
vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const wrap = (ui: React.ReactElement) =>
  render(
    <MemoryRouter>
      <IntlProvider locale="en" defaultLocale="en">
        {ui}
      </IntlProvider>
    </MemoryRouter>,
  );

const BASE_PROPS: ZimmProductCardContentProps = {
  name: 'Natura Long Sleeve Linen Mini Dress',
  headingLevel: 'h3',
  href: '/product/123',
  showAttributes: false,
  showBag: false,
  showSizeChips: false,
  showNotifyMe: false,
};

const SIZES: ZimmSizeChipValue[] = [
  { value: 'xs', label: 'XS' },
  { value: 's', label: 'S' },
];

describe('ZimmProductCardContent — name renders as a link to the PDP', () => {
  test('renders the product name as a heading, linked to href, at the given heading level', () => {
    wrap(<ZimmProductCardContent {...BASE_PROPS} name="Natura Dress" headingLevel="h2" href="/product/123" />);
    const link = screen.getByRole('link', { name: 'Natura Dress' });
    expect(link).toHaveAttribute('href', '/product/123');
    expect(screen.getByRole('heading', { level: 2, name: 'Natura Dress' })).toBeInTheDocument();
  });

  test('renders a different heading level when headingLevel changes', () => {
    wrap(<ZimmProductCardContent {...BASE_PROPS} headingLevel="h2" />);
    expect(screen.getByRole('heading', { level: 2 })).toBeInTheDocument();
    expect(screen.queryByRole('heading', { level: 3 })).not.toBeInTheDocument();
  });
});

describe('ZimmProductCardContent — bag control', () => {
  test('is absent when showBag is false', () => {
    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag={false} />);
    expect(screen.queryByRole('button', { name: 'Add to bag' })).not.toBeInTheDocument();
  });

  test('renders a labelled native button when showBag is true', () => {
    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag />);
    const button = screen.getByRole('button', { name: 'Add to bag' });
    expect(button.tagName).toBe('BUTTON');
    expect(button).not.toBeDisabled();
    // The organism's own recipe needs a stable slot to hide this on mobile for PLP/PDP (Figma:
    // the Mobile Card-content instance's "Icons" frame is hidden="true" there, unlike Desktop and
    // unlike Wishlist's own Mobile instance) — added alongside the SFCC-236 Step 6 visual audit.
    expect(button.closest(`[data-card-slot="${CARD_SLOT.bag}"]`)).not.toBeNull();
  });

  test('calls onAddToBag when clicked while available', async () => {
    const onAddToBag = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag onAddToBag={onAddToBag} />);
    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
    expect(onAddToBag).toHaveBeenCalledTimes(1);
  });

  test('is disabled via the native disabled attribute when isUnavailable is true', () => {
    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag isUnavailable />);
    expect(screen.getByRole('button', { name: 'Add to bag' })).toBeDisabled();
  });

  test('never calls onAddToBag when isUnavailable, even when a click is dispatched directly', () => {
    const onAddToBag = vi.fn();
    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag isUnavailable onAddToBag={onAddToBag} />);
    const button = screen.getByRole('button', { name: 'Add to bag' });
    // A native `disabled` button never dispatches a click at all — this is the browser's own
