describe('ZimmProductCardContent — notify-me control', () => {
  // Changed 2026-09-08, Marcel's explicit decision (see this component's own `showNotifyMeButton`
  // comment): the real Notify Me feature has no handler to wire yet, so the button now ships
  // visible-but-inert on `showNotifyMe` alone, rather than requiring a real `onNotifyMe` too.
  test('renders, inert, when showNotifyMe is true and onNotifyMe is not supplied', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCardContent {...BASE_PROPS} showNotifyMe />);
    const button = screen.getByRole('button', { name: 'Notify me' });
    expect(button.tagName).toBe('BUTTON');
    // Genuinely inert, not merely present: a real click must not throw with no handler wired.
    // PostBuild fix round, Fix 2 (2026-09-15, CodeRabbit finding on PR #116). The previous
    // `await expect(user.click(button)).resolves.not.toThrow()` form can never fail here even
    // when the click handler genuinely throws (confirmed via mutation testing) — but so does the
    // seemingly obvious `await user.click(button)` replacement suggested alongside this finding:
    // React's DEV-mode event dispatch (`invokeGuardedCallbackDev`,
    // node_modules/react-dom/cjs/react-dom.development.js:4112-4243) runs the click handler via a
    // real, synchronous `fakeNode.dispatchEvent(evt)` — and per the DOM spec, an event listener
    // throwing during `dispatchEvent` does not propagate out of that call or reject any promise
    // built on it; it is reported separately (here, via jsdom's default virtual console). Verified
    // directly: with this button's own handler temporarily forced to throw, `user.click(button)`'s
    // returned promise still resolved without rejecting, while `console.error` was called (twice)
    // with the thrown error's own stack trace — confirming that is the real, observable channel a
    // genuine throw takes here, not a promise rejection. Asserting against that channel instead:
    // spy on `console.error`, click, and assert it was never called — restored immediately after so
    // it can't affect any other test in this file (same idiom as the existing `console.warn` spy at
    // resolveByRegion.test.ts:70, applied to `error` instead of `warn`).
    const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
    await user.click(button);
    expect(consoleErrorSpy).not.toHaveBeenCalled();
    consoleErrorSpy.mockRestore();
  });

  test('is absent when onNotifyMe is supplied but showNotifyMe is false', () => {
    wrap(<ZimmProductCardContent {...BASE_PROPS} showNotifyMe={false} onNotifyMe={vi.fn()} />);
    expect(screen.queryByRole('button', { name: 'Notify me' })).not.toBeInTheDocument();
  });

  test('renders a real, labelled button and calls onNotifyMe on click when both conditions hold', async () => {
    const onNotifyMe = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmProductCardContent {...BASE_PROPS} showNotifyMe onNotifyMe={onNotifyMe} />);
    const button = screen.getByRole('button', { name: 'Notify me' });
    expect(button.tagName).toBe('BUTTON');
    // The organism's own recipe needs a stable slot to hover-gate this button (hidden by default
    // on hover-capable devices, always visible on touch — see zimmProductCard.css.ts's Fix C) —
    // added alongside the SFCC-236 Step 6 visual audit that found notify-me was rendering
    // unconditionally instead of matching Figma's hover-reveal behaviour.
    expect(button).toHaveAttribute('data-card-slot', 'notifyMe');
    await user.click(button);
    expect(onNotifyMe).toHaveBeenCalledTimes(1);
  });
});

