/**
 * Real-recipe assertions — bypasses the useMultiStyleConfig mock entirely, same technique as
 * zimmProductCardMedia/index.test.tsx's own "Fix 1" block. The component-level tests above all
 * render through the flat mock at the top of this file, which can't see whether the real recipe
 * ever regresses the focus ring or accidentally hides the size-chip slot — both are exactly the
 * kind of CSS-only, "would survive a refactor invisibly if broken" behaviour testing.md calls
 * out, and the focus-ring gap specifically has already been caught twice in this build (Step 2,
 * Step 4) after being missed by mocked component tests alone.
 */
describe('ZimmProductCardContent — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
  const EXPECTED_FOCUS_VISIBLE = {
    outline: 'var(--zimm-focus-ring)',
    outlineOffset: 'var(--zimm-focus-ring-offset-default)',
  };

  test('nameLink, bagButton and notifyMeButton all carry the standard keyboard focus-visible outline', () => {
    const style = ZimmProductCardContentRecipe.baseStyle({});
    expect((style.nameLink as Record<string, unknown>)._focusVisible).toEqual(EXPECTED_FOCUS_VISIBLE);
    expect((style.bagButton as Record<string, unknown>)._focusVisible).toEqual(EXPECTED_FOCUS_VISIBLE);
    expect((style.notifyMeButton as Record<string, unknown>)._focusVisible).toEqual(EXPECTED_FOCUS_VISIBLE);
  });

  test('sizeChipWrapper never sets display:none — visibility belongs to the Step 6 organism, not this recipe', () => {
    const style = ZimmProductCardContentRecipe.baseStyle({});
    expect((style.sizeChipWrapper as Record<string, unknown>).display).not.toBe('none');
  });

  test('bagButton cursor and colour resolve per the disabled style prop', () => {
    const enabled = ZimmProductCardContentRecipe.baseStyle({ disabled: false });
    const disabled = ZimmProductCardContentRecipe.baseStyle({ disabled: true });

    expect(enabled.bagButton.cursor).toBe('pointer');
    expect(disabled.bagButton.cursor).toBe('not-allowed');
    expect(enabled.bagButton.color).toBe('var(--zimm-color-text-default)');
    expect(disabled.bagButton.color).toBe('var(--zimm-color-text-muted)');
  });

  // Root's outer padding was a real, confirmed gap (no padding at all, on any breakpoint) found
  // by cross-checking the Mobile Figma variant the docblock cited but never actually verified —
  // this is the "class of bug caught by a recipe change with no test exercising the real CSS"
  // that has bitten this build twice already (Step 2, Step 4), so it gets its own assertion here
  // rather than trusting the docblock's citation alone.
  test('root carries the mobile-first base padding, overridden at the desktop breakpoint', () => {
    const style = ZimmProductCardContentRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;

    // Base (non-media-query) values are the Mobile ones — Figma node 40002163:37103.
    expect(root.paddingTop).toBe('var(--zimm-scale-m)'); // 16px
    expect(root.paddingInline).toBe('var(--zimm-scale-2xl)'); // 32px

    // Desktop override lives under the real registered breakpoint token, not a hardcoded string
    // — Figma node 40002163:41443. Direct property access (not toHaveProperty) because the key
    // itself contains characters toHaveProperty's dot-path parsing isn't meant to walk.
    const mediaQueryKey = `@media (min-width: ${breakpoints.md})`;
    expect(Object.prototype.hasOwnProperty.call(root, mediaQueryKey)).toBe(true);
    const desktop = root[mediaQueryKey] as Record<string, unknown>;
    expect(desktop.paddingTop).toBe('var(--zimm-scale-2xl)'); // 32px
    expect(desktop.paddingInline).toBe('var(--zimm-scale-3xl)'); // 40px
  });
});

import { useMediaQuery } from '@chakra-ui/react';
import { breakpoints } from 'app/theme/foundation';
import { RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS, RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT } from 'app/constants';

/**
 * SFCC-83 — resolves how many Recently Viewed cards should be visible for the current real
 * breakpoint. Fixes a real, live-confirmed bug (2026-09-10): `useBreakpointValue` can only switch
 * at this site's own registered Chakra breakpoints (`base`/`sm`/`md`/`lg`/`xl`/`2xl`), but the
 * rail's own card-width styling (`zimmRecentlyViewedRail.css.ts`'s `DESKTOP_UP_QUERY`) switches to
 * Desktop sizing at 1024px — this component's own real Figma Desktop threshold, not this site's
 * shared `breakpoints.xl` (1280px). Calling `useBreakpointValue(RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS)`
 * directly (the previous approach) meant the item-count cap only ever stepped to 5 at 1280px,
 * leaving a 1024–1280px gap where the card row was already styled for 5 slots but only 3 cards
 * were allowed to render — see `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS`'s own correction note
 * (`app/constants/index.ts`) for the full incident.
 *
 * Two raw `useMediaQuery` checks, not `useBreakpointValue`, because the Desktop threshold this
 * needs to match (1024px) has no corresponding entry in this site's registered breakpoint scale
 * to key an object against — `breakpoints.md` (768px) still correctly matches both this site's
 * shared value and the rail's own Tablet start, so only the Desktop half needs the raw-query
 * treatment. Checked widest-first (Desktop, then Tablet) since both are plain `min-width` queries
 * that both remain true well past their own threshold — a real 1440px viewport matches both, and
 * only the order of these checks (not a mutually-exclusive range) picks the right one.
 *
 * SSR-safe by the same construction `useBreakpointValue` already relied on: both media queries
 * default to `false` before the client-side match resolves, so this correctly falls through to
 * `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base` (the smallest/mobile count) on the very first
 * render, matching this hook's two callers' own prior documented fallback behaviour.
 *
 * @returns The number of cards the rail should render/cap to at the current real breakpoint.
 */
export const useRecentlyViewedRailVisibleCount = (): number => {
  const [isTabletUp] = useMediaQuery(`(min-width: ${breakpoints.md})`);
  const [isDesktop] = useMediaQuery(`(min-width: ${RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT})`);

  if (isDesktop) return RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.xl;
  if (isTabletUp) return RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.md;
  return RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base;
};

import React from 'react';
import type { ReactNode } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';
import { useRecentlyViewedRailVisibleCount } from 'app/hooks/useRecentlyViewedRailVisibleCount';
import { ZimmProductCard } from '../zimmProductCard';
import type { ZimmProductCardBaseProps, ZimmProductCardRecentlyViewedVariation } from '../zimmProductCard';

/**
 * The narrow `recentlyViewed`-only slice of the full `ZimmProductCardProps` union — this
 * component only ever renders that one variation (see this file's own module docblock), so
 * `cards` below is typed against exactly that, not the full four-variation union (narrowed
 * 2026-09-15, CodeRabbit finding, confirmed: the wider union let a caller pass e.g. a
 * `plp`-shaped card with no compile error, even though nothing here would ever render its
 * `plp`-only fields). Both halves are real, already-exported types from `zimmProductCard` —
 * see that module's own `ZimmProductCardBaseProps`/`ZimmProductCardRecentlyViewedVariation`.
 */
export type ZimmRecentlyViewedCardProps = ZimmProductCardBaseProps & ZimmProductCardRecentlyViewedVariation;

// Same `chakra(RouteLink)` wrap this component family already establishes for its own internal
// links (zimmProductCard/index.tsx's `MediaOnlyCardLink`, zimmProductCardContent/index.tsx's
// `ProductNameLink`) — used here for the See-Full-History link, which navigates to the SFCC-84
// Recently Viewed Full History page, an internal route, not an external URL.
const SeeAllLink = chakra(RouteLink);

export type ZimmRecentlyViewedRailProps = {
  /**
   * Typed as `ReactNode`, not `string` — this component owns no copy/intl (the container, A6,
   * does). **Styling resolved 2026-09-08** (was previously left unstyled pending confirmation —
   * live Storybook testing caught the resulting bug: the title rendered in the ambient body
   * weight, Futura Round 400, instead of the design's intended weight): this component now
   * applies `textStyle="heading3"` itself when rendering `title`, matching the exact spec
   * confirmed against the Full History page's own title bar this same session (Figma
   * `Default/h3-strong` — Futura Round, 16px/18 line-height, weight 500, letter-spacing -0.12px,
   * uppercase — cross-checked against this codebase's registered `heading3` token, an exact
   * match). Applying it here rather than requiring every caller to pre-style the title guarantees
   * the design intent regardless of what a caller passes; a caller supplying an already fully
   * styled element can still override any of this via its own more-specific styling.
   */
  title: ReactNode;
  /**
   * Rendered in the exact order received (AC 2: most-recent-first, left to right) — no sorting or
   * reordering happens here. Capped to `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS` for the current real
   * breakpoint regardless of length — a hard cap, not a "fits before scrolling" soft limit (see
   * that constant's own comment, app/constants/index.ts, and this component's own render-body
   * comment below for why the cap has to live here rather than in the request that produced this
   * array).
   */
  cards: readonly ZimmRecentlyViewedCardProps[];
  /** Href to the SFCC-84 Recently Viewed Full History page. The See-Full-History link only
   *  renders when this is provided — see the render body below. */
  seeAllHref?: string;
  /**
   * No default/fallback text is supplied when this is omitted while `seeAllHref` is provided —
   * this component owns no copy or intl (see the module docblock), so inventing an English
   * fallback here would risk shipping untranslated text on non-English storefronts. In real usage
   * the container (A6) is expected to always supply this alongside `seeAllHref`.
   */
  seeAllLabel?: string;
};

const ZIMM_RECENTLY_VIEWED_RAIL_RECIPE = 'ZimmRecentlyViewedRail';

/**
 * SFCC-83 — the Recently Viewed rail organism (build plan section A5). Purely presentational:
 * data arrives as props, no data-fetching, no `useEinstein`, no `useIntl` — see
 * .claude/rules/components.md's container/presentational split. The container (A6) is
 * responsible for building `cards` (via A3's Einstein-rec-to-card mapper) and supplying
 * `title`/`seeAllLabel` copy. **Corrected 2026-09-15 (PostBuild fix round, Fix 4):** this line
 * previously credited "A4's `hasRecentlyViewed`" — the now-deleted `useRecentlyViewedHistory`
 * hook — with gating this component's visibility, in the present tense, well after that hook was
 * removed (build plan step E4). The real visibility gate has lived entirely in the container since
 * build plan step E1 (`recommended-products/index.tsx`'s own `!recommendations?.recs?.length`
 * check) — this component has never gated its own visibility beyond the `visibleCards.length === 0`
 * guard below; it renders whatever `cards` it is given, or nothing.
 *
 * Structure mirrors Figma exactly: a `header` row (title left, the See-Full-History link right)
 * above a `group` of `ZimmProductCard`s. No rail-level arrow buttons — `ZimmProductCardMedia`
 * already carries its own intra-card carousel arrows, and a second set at the rail level would
 * collide with them (see zimmRecentlyViewedRail.css.ts's own docblock for the Figma node
 * evidence).
 *
 * **`group`'s horizontal scroll/scroll-snap (zimmRecentlyViewedRail.css.ts) is a narrow-viewport
 * safety net, not the "more cards exist, scroll to see them" mechanism it might look like.**
 * Confirmed with Marcel (2026-09-08): the per-breakpoint card count below is a hard cap — a
 * shopper on a real, design-reference-width device never has more cards to scroll to than the
 * cap allows; "more history exists" is surfaced via the See-Full-History link (the container's
 * own job), not via scrolling this rail further. The scroll/scroll-snap CSS stays
 * meaningful only for a real device narrower than the design reference itself (e.g. a phone
 * under ~402px), where the capped card count can still slightly overflow the actual viewport.
 *
 * `cards` is typed as `ZimmRecentlyViewedCardProps` (`ZimmProductCardBaseProps &
 * ZimmProductCardRecentlyViewedVariation`, declared above) — not the full `ZimmProductCardProps`
 * union this step's own given component contract originally specified verbatim (narrowed
 * 2026-09-15, CodeRabbit finding, confirmed: this component only ever renders the
 * `recentlyViewed` variation, so the wider union let a caller pass e.g. a `plp`-shaped card with
 * no compile error, even though nothing here would ever render its `plp`-only fields). This
 * component therefore still spreads each entry straight into `ZimmProductCard`
 * (`<ZimmProductCard {...card} />`) rather than forcing `variation: 'recentlyViewed'` onto every
 * card itself — every entry already carries that variation by construction (A3's mapper produces
 * `recentlyViewed`-shaped cards) and now by the type itself, since `ZimmRecentlyViewedCardProps`
 * has no other variation to be. Type-only change: `ZimmProductCard`'s own prop type is still the
 * full union, and a `ZimmRecentlyViewedCardProps` value is one real member of it, so this compiles
 * and renders identically to before.
 *
 * `data-testid="product-card"` / `data-product-id` on each rendered card come from
 * `ZimmProductCard`'s own root (zimmProductCard/index.tsx: "a DOM hook for QA automation/
 * analytics") — this component adds no additional per-card test hook of its own.
 */
export const ZimmRecentlyViewedRail = ({ title, cards, seeAllHref, seeAllLabel }: ZimmRecentlyViewedRailProps) => {
  const styles = useMultiStyleConfig(ZIMM_RECENTLY_VIEWED_RAIL_RECIPE, {});

  // Cap is enforced here, client-side, regardless of how many cards were passed in — the data
  // source (Einstein's own `recommendations.recs`, wired in build plan step E1) does not itself
  // honour a requested limit, and per-breakpoint capping is this component's own presentational
  // concern, not the container's. Falls back to the smallest (base/mobile) count on the very first render
  // before the client-side media-query match resolves (see RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS's
  // own comment, app/constants/index.ts, for why this is a hard per-breakpoint cap, not a "fits
  // before scrolling" soft limit). A slice, never a sort — order is otherwise untouched (AC 2).
  //
  // `useRecentlyViewedRailVisibleCount()`, not a direct `useBreakpointValue` call (corrected
  // 2026-09-10 — see that hook's own docblock for the live-confirmed bug this closes): this
  // component's own Desktop card-width styling (zimmRecentlyViewedRail.css.ts's
  // `DESKTOP_UP_QUERY`) switches at 1024px, not this site's shared `breakpoints.xl` (1280px) that
  // `useBreakpointValue` would have resolved against — the two disagreeing meant a real, narrow
  // window (1024–1280px) where cards were already styled for 5 slots but only 3 were allowed to
  // render.
  const maxVisibleCards = useRecentlyViewedRailVisibleCount();
  const visibleCards = cards.slice(0, maxVisibleCards);

  // Guards against an empty/all-capped-out `cards` array — an empty rail renders nothing at all,
  // not an empty shell. Corrected 2026-09-15 (PostBuild fix round, Fix 4): this used to describe
  // itself as a "second guard behind A4's own visibility gate", A4 being the now-deleted
  // `useRecentlyViewedHistory` hook's `hasRecentlyViewed` check (removed build plan step E4). The
  // real visibility gate is the container's own `!recommendations?.recs?.length` check
  // (`recommended-products/index.tsx`, build plan step E1) — this component has never gated its
  // own visibility on anything besides this one check.
  if (visibleCards.length === 0) {
    return null;
  }

  return (
    <chakra.div __css={styles.container} data-testid="recently-viewed-rail">
      <chakra.div __css={styles.header}>
        {/* flex/minWidth match Figma's own title node (flex: 1 0 0, min-w-px) — grows to fill
            whatever `header`'s own gap + the link's width don't claim, and can shrink below its
            own text's intrinsic width rather than force an overflow. See zimmRecentlyViewedRail.css.ts's
            own "TITLE/LINK SPACING" docblock section. */}
        <chakra.span textStyle="heading3" flex="1 0 0" minWidth={0}>
          {title}
        </chakra.span>
        {seeAllHref && seeAllLabel && (
          <SeeAllLink to={seeAllHref} textStyle="linkLg" __css={styles.seeAllLink}>
            {seeAllLabel}
          </SeeAllLink>
        )}
      </chakra.div>
      <chakra.div __css={styles.group} data-testid="recently-viewed-rail-group">
        {visibleCards.map((card) => (
          <chakra.div key={card.id} __css={styles.card}>
            <ZimmProductCard {...card} />
          </chakra.div>
        ))}
      </chakra.div>
    </chakra.div>
  );
};

