file.content:
test('returns the global fallback when no regional entry exists', () => {
  const global = entry('global');
  expect(pickMostSpecificByRegion([global], 'ZimmermannUS')).toBe(global);
});

test('a US-scoped override wins over a broader global entry', () => {
  const global = entry('global');
  const usOverride = entry('us-override', ['ZimmermannUS']);
  expect(pickMostSpecificByRegion([global, usOverride], 'ZimmermannUS')).toBe(usOverride);
});

test('narrower regions array wins over a broader (but still eligible) one', () => {
  const broad = entry('broad', ['ZimmermannUS', 'ZimmermannAU']);
  const narrow = entry('narrow', ['ZimmermannUS']);
  expect(pickMostSpecificByRegion([broad, narrow], 'ZimmermannUS')).toBe(narrow);
});

describe('tie-break', () => {
  beforeEach(() => {
    vi.spyOn(console, 'warn').mockImplementation(() => {});
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  test('two equally-scoped entries resolve to the most recently updated, and warn', () => {
    const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
    const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
    expect(pickMostSpecificByRegion([older, newer], 'ZimmermannUS')).toBe(newer);
    expect(console.warn).toHaveBeenCalledTimes(1);
  });

  test('distinct timestamps resolve the same way whichever order they arrive in', () => {
    const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
    const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
    expect(pickMostSpecificByRegion([newer, older], 'ZimmermannUS')).toBe(newer);
    // Previously the warn lived inside the `candidateUpdatedAt > bestUpdatedAt` branch, so a tie
    // already arriving newest-first resolved silently. Asserting it here is what pins that.

