import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

function ThrowingButton() {
  return (
    <button
      onClick={() => {
        throw new Error('forced throw for independent verification');
      }}
    >
      Click me
    </button>
  );
}

describe('VERIFY: does a bare await user.click() surface a thrown handler error in this stack?', () => {
  test('resolves.not.toThrow() form: passes trivially (known no-op, per CodeRabbit finding)', async () => {
    const user = userEvent.setup();
    render(<ThrowingButton />);
    const button = screen.getByRole('button', { name: 'Click me' });
    await expect(user.click(button)).resolves.not.toThrow();
  });

  test('bare "await user.click(button)": does this line itself throw/reject when the handler throws?', async () => {
    const user = userEvent.setup();
    render(<ThrowingButton />);
    const button = screen.getByRole('button', { name: 'Click me' });
    // If the implementer's claim is correct, this line completes normally (no rejection) even
    // though the onClick handler above genuinely threw -- meaning this whole test PASSES despite
    // the throw, proving the bare-await suggestion is a no-op here too.
    await user.click(button);
    expect(true).toBe(true);
  });

  test('console.error spy DOES observe the thrown error (the real, working channel)', async () => {
    const user = userEvent.setup();
    render(<ThrowingButton />);
    const button = screen.getByRole('button', { name: 'Click me' });
    const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
    await user.click(button);
    expect(spy).toHaveBeenCalled();
    spy.mockRestore();
  });
});
